def solve(table, question, choices):
    import re
    q = question.lower()
    cols = list(table)
    rows = len(table[cols[0]])
    def num(s):
        m = re.search(r'-?\d[\d,]*(?:\.\d+)?', str(s).replace('$','').replace('%',''))
        return float(m.group().replace(',','')) if m else None
    def text(s): return str(s).strip()
    # find numeric column
    num_cols = []
    for c in cols:
        vals = [num(x) for x in table[c]]
        if sum(v is not None for v in vals) >= max(1, rows//2):
            num_cols.append((c, vals))
    # find text column (likely answer column)
    text_cols = [c for c in cols if c not in [nc for nc,_ in num_cols]]
    # determine metric column: prefer column whose name appears in question, else numeric col with max variance
    metric = None
    for c, vals in num_cols:
        if c.lower() in q:
            metric = (c, vals); break
    if metric is None and num_cols:
        metric = num_cols[0]
    # determine answer column: prefer column whose name appears in question
    ans_col = None
    for c in text_cols:
        if c.lower() in q:
            ans_col = c; break
    if ans_col is None:
        # prefer column named like Nation/Country/Venue/Player/Team
        for pref in ['nation','country','venue','player','team','city']:
            for c in text_cols:
                if pref in c.lower():
                    ans_col = c; break
            if ans_col: break
    if ans_col is None:
        ans_col = text_cols[0] if text_cols else cols[0]
    # filter rows by question keywords (e.g., season, year)
    filtered = list(range(rows))
    for c in cols:
        for v in set(table[c]):
            if isinstance(v,str) and len(v)>2 and v.lower() in q:
                filtered = [i for i in range(rows) if table[c][i]==v]
                break
        if filtered != list(range(rows)): break
    if not filtered: filtered = list(range(rows))
    # aggregate
    if 'most participants' in q or 'most' in q and 'participants' in q:
        # count rows per answer value
        from collections import Counter
        cnt = Counter(table[ans_col][i] for i in filtered)
        best = max(cnt, key=cnt.get)
        return best
    # default: max of metric
    vals = metric[1]
    best_i = max(filtered, key=lambda i: (vals[i] if vals[i] is not None else -1e18))
    # handle ties: return first
    return text(table[ans_col][best_i])

