def solve(table, question, choices):
    import re
    q = question.lower()
    cols = list(table)
    rows = len(table[cols[0]]) if cols else 0
    def cell(col, i):
        v = table.get(col, [])
        return v[i] if i < len(v) else ""
    def find_col(*keys):
        for c in cols:
            cl = c.lower()
            if any(k in cl for k in keys):
                return c
        return None
    def num(s):
        m = re.search(r'-?\d+(?:\.\d+)?', str(s).replace('$','').replace(',','').replace('%',''))
        return float(m.group()) if m else None
    # same position in two columns
    if 'same position' in q:
        m = re.search(r'in ([a-z ]+?) as in ([a-z ]+?)', q)
        if m:
            a, b = m.group(1).strip(), m.group(2).strip()
            ca = find_col(a) or find_col(a.split()[0])
            cb = find_col(b) or find_col(b.split()[0])
            if ca and cb:
                for i in range(rows):
                    na, nb = num(cell(ca,i)), num(cell(cb,i))
                    if na is not None and nb is not None and na == nb:
                        col = find_col('single','name','player') or cols[0]
                        return cell(col, i)
        return ""
    # ranked last in a column
    if 'ranked last' in q or 'last in' in q:
        m = re.search(r'(?:in|of) the ([a-z0-9 ]+?) column', q)
        col = find_col(m.group(1).strip()) if m else None
        if col:
            best = None; best_rank = None
            for i in range(rows):
                r = num(cell(col,i))
                if r is not None and (best_rank is None or r > best_rank):
                    best_rank = r; best = i
            if best is not None:
                col2 = find_col('player','name','single') or cols[0]
                return cell(col2, best)
        return ""
    # first player picked who attended school in X
    if 'first player' in q and 'school' in q:
        m = re.search(r'school in ([a-z ]+?)(?:\\?$|\\?\\?)', q)
        m = re.search(r'school in ([a-z ]+)', q)
        if m:
            loc = m.group(1).strip()
            col = find_col('school','club')
            for i in range(rows):
                if col and loc in cell(col,i).lower():
                    col2 = find_col('player','name') or cols[0]
                    return cell(col2, i)
        return ""
    # position/number questions
    word = {'one':1,'two':2,'three':3,'four':4,'five':5,'six':6,'seven':7,'eight':8,'nine':9,'ten':10}
    m2 = re.search(r'(?:position|number) (one|two|three|four|five|six|seven|eight|nine|ten|\\d+)', q)
    pos = None
    if m2:
        tok = m2.group(1)
        pos = word.get(tok, int(tok) if tok.isdigit() else None)
    if pos is not None:
        idx = pos - 1
        if 'vacant' in q or 'who holds' in q or 'officer' in q:
            col = find_col('officer') or find_col('incumbent') or cols[0]
            return cell(col, idx)
        col = find_col('officer','incumbent','name','venue','winner') or cols[0]
        return cell(col, idx)
    if 'first' in q:
        col = find_col('venue','name','winner','tournament') or cols[0]
        return cell(col, 0)
    if 'top' in q or 'incumbent' in q:
        col = find_col('incumbent') or cols[0]
        return cell(col, 0)
    if 'winner' in q:
        col = find_col('winner')
        return cell(col, 0)
    if 'venue' in q:
        col = find_col('venue')
        return cell(col, 0)
    if 'name' in q:
        col = find_col('name','venue','winner','tournament') or cols[0]
        return cell(col, 0)
    return cell(cols[0], 0) if cols else ""

def solve(table, question, choices):
    cols = list(table)
    rows = list(zip(*table.values()))
    q = question.lower()
    def col(name):
        for c in cols:
            if c.lower() == name.lower(): return c
        return None
    def find_row(val):
        for i, r in enumerate(rows):
            for c in cols:
                if r[cols.index(c)].lower() == val.lower(): return i
        return -1
    def after_val(val, colname):
        i = find_row(val)
        if i < 0: return None
        c = col(colname)
        if not c: return None
        if i+1 < len(rows): return rows[i+1][cols.index(c)]
        return None
    if "after" in q:
        target = q.split("after")[1].strip().rstrip("?").strip()
        if "guest judge" in q:
            return after_val(target, "Guest judge(s)") or ""
        if "opponent" in q:
            return after_val(target, "Opponent in the final") or ""
        if "coach" in q:
            return after_val(target, "Name") or ""
        if "name" in q:
            return after_val(target, "Name") or ""
        if "reigned" in q:
            i = find_row(target)
            if i >= 0:
                for j in range(i+1, len(rows)):
                    if rows[j][cols.index(col("Wrestler:"))].lower() != target.lower():
                        return rows[j][cols.index(col("Wrestler:"))]
            return ""
        if "singles match" in q:
            m = q.split("was")[1].split("in")[0].strip()
            i = find_row(target)
            if i >= 0 and i+1 < len(rows):
                mt = rows[i+1][cols.index(col("Match Type"))]
                te = rows[i+1][cols.index(col("Team Europe"))]
                tu = rows[i+1][cols.index(col("Team USA"))]
                if mt.lower() == "singles" and (te.lower() == m or tu.lower() == m):
                    return "Yes"
            return "No"
    return ""

