    def num(s):
        if s is None: return None
        s = str(s).strip().lower()
        if not s or s in ("-", "–", "—", "no data", "n/a", "none"): return None
        s = s.split("(")[0].strip()
        s = s.replace("$", "").replace(",", "").replace("%", "")
        for u in ["billions", "billion", "million", "millions", "thousand", "thousands", "us$", "us", "usd", "dollars", "$"]:
            s = s.replace(u, "")
        s = s.replace("†", "").replace("‡", "").strip()
        try: return float(s)
        except: return None
    def col_vals(name): return [num(x) for x in table[name]]
    def col_raw(name): return [str(x) for x in table[name]]
    # find year/date context
    year = None
    import re
    m = re.search(r"\b(19|20)\d{2}\b", q)
    if m: year = m.group(0)
    # find team/player context
    team = None
    for t in ["india", "australia", "england", "west indies", "new zealand", "pakistan", "zimbabwe", "sri lanka", "ireland", "south africa", "bangladesh", "afghanistan", "usa", "united states", "norway", "sweden", "finland", "hungary", "czechoslovakia", "great britain"]:
        if t in q: team = t; break
    player = None
