        if p in q: player = p; break
    # match rows
    matched = []
    for i in range(rows):
        row_text = " ".join(str(table[c][i]).lower() for c in cols)
        ok = True
        if year and year not in row_text: ok = False
        if team:
            # check team column or opposing team
            team_col = None
            for c in cols:
                if c.lower() in ("team", "teams", "opponent", "opposing team"): team_col = c; break
            if team_col:
                tv = str(table[team_col][i]).lower()
                if team not in tv and team.replace(" ", "") not in tv.replace(" ", ""): ok = False
            else:
                if team not in row_text: ok = False
