            pcol = None
            for c in cols:
                if c.lower() in ("player", "shooter", "name", "athlete"): pcol = c; break
            if pcol:
                pv = str(table[pcol][i]).lower()
                if player not in pv: ok = False
            else:
                if player not in row_text: ok = False
        if ok: matched.append(i)
