    elif "number of points" in q or "points" in q:
        for c in cols:
            if c.lower() == "total": target = c; break
        if not target:
            for c in cols:
                if "total" in c.lower(): target = c; break
    elif "deaths" in q:
        for c in cols:
            if "deaths" in c.lower(): target = c; break
    elif "injuries" in q:
        for c in cols:
            if "injuries" in c.lower(): target = c; break
    elif "funding" in q:
        for c in cols:
            if "funding" in c.lower(): target = c; break
    elif "sales" in q:
        for c in cols:
            if "sales" in c.lower(): target = c; break
    elif "score" in q:
        for c in cols:
            if c.lower() == "score": target = c; break
    elif "rank" in q:
        for c in cols:
            if c.lower() == "rank": target = c; break
    elif "place" in q:
        for c in cols:
            if c.lower() == "place": target = c; break
    if not target:
        # default: numeric column with most data
        best = None; best_n = -1
        for c in cols:
            vals = col_vals(c)
            n = sum(1 for v in vals if v is not None)
            if n > best_n: best_n = n; best = c
        target = best
    vals = [num(table[target][i]) for i in matched]
    vals = [v for v in vals if v is not None]
    if not vals: return ""
    # sum if multiple rows and question asks total/number
    if "total" in q or "number of" in q or "how many" in q or "how much" in q:
        total = sum(vals)
        if total == int(total): ans = str(int(total))
        else: ans = str(total)
    else:
        ans = str(vals[0]) if len(vals) == 1 else str(vals[0])
    # choices
    if choices:
        for ch in choices:
            if str(ch).strip() == ans: return ch
        # try numeric match
        try:
            av = float(ans)
            for ch in choices:
