    words = {'first':1,'second':2,'third':3,'fourth':4,'fifth':5,'sixth':6,'seventh':7,'eighth':8,'ninth':9,'tenth':10,'eleventh':11,'twelfth':12,'thirteenth':13,'fourteenth':14,'fifteenth':15,'sixteenth':16,'seventeenth':17,'eighteenth':18,'nineteenth':19,'twentieth':20}
    if tok in words:
        n = words[tok]
    else:
        n = int(re.match(r'(\d+)', tok).group(1))
    if 'last' in q:
        idx = rows - 1
    else:
        idx = n - 1
    # find target column: column whose header words appear in question, else the column with most non-empty cells
    target = None
    for c in cols:
        cl = c.lower()
        if cl in q:
            target = c
            break
    if target is None:
        # look for nouns in question matching column header words
