        for c in cols:
            words_c = set(re.findall(r'[a-z]+', c.lower()))
            score = sum(1 for w in words_c if w in q)
            if score > bestscore:
                bestscore = score; best = c
        if bestscore == 0:
            raise ValueError("no column")
        target = best
    # filter rows by episode/number mentions if question mentions a number/episode
    # e.g. "episode 220"
    ep = re.search(r'episode\s+(\d+)', q)
    if ep:
        num = ep.group(1)
