    # exclude total rows
    mask = [True]*rows
    for i in range(rows):
        for c in cols:
            if str(table[c][i]).lower().strip() == 'total':
                mask[i] = False
                break
    # find mentioned values (names/opponents)
    mentioned = []
    for c in cols:
        for v in table[c]:
            s = str(v).lower().strip()
            if len(s) > 2 and s in q:
                mentioned.append((c, v))
    # filter rows by mentioned values (any match)
    if mentioned:
        newmask = [False]*rows
        for i in range(rows):
            for c, v in mentioned:
                if str(table[c][i]).lower().strip() == str(v).lower().strip():
                    newmask[i] = True
                    break
        mask = [m and n for m, n in zip(mask, newmask)]
    # date filter: "on october 4, 2008" or "october 4"
    m = re.search(r'on\s+([a-z]+)\s+(\d{1,2})(?:,\s*(\d{4}))?', q)
    if m:
        month = m.group(1)
        day = m.group(2)
        year = m.group(3)
        month_map = {'january':'jan','february':'feb','march':'mar','april':'apr','may':'may','june':'jun','july':'jul','august':'aug','september':'sep','october':'oct','november':'nov','december':'dec'}
        mon = month_map.get(month, month)
        newmask = [False]*rows
        for i in range(rows):
            for c in cols:
                s = str(table[c][i]).lower()
                if mon in s and day in s:
                    if year is None or year in s:
                        newmask[i] = True
                        break
        mask = [a and b for a, b in zip(mask, newmask)]
    # numeric columns
    numcols = []
    for c in cols:
        vals = [num(v) for v in table[c]]
        if sum(1 for v in vals if v is not None) >= max(1, rows*0.5):
            numcols.append(c)
    # target column: header word in question
    target = None
    for c in numcols:
        words = re.findall(r'[a-z]+', c.lower())
        if any(w in q for w in words):
            target = c; break
    if target is None:
        cand = [c for c in numcols if c.lower() != 'total']
        target = cand[0] if cand else None
    if target is None:
        raise ValueError('no numeric column')
    # special: score column -> sum of both sides
    if target.lower() == 'score':
        total = 0.0
        for i in range(rows):
            if mask[i]:
                s = str(table[target][i])
                parts = re.split(r'[–-]', s)
                if len(parts) == 2:
                    a = num(parts[0]); b = num(parts[1])
                    if a is not None and b is not None:
                        total += a + b
        if total == int(total): return str(int(total))
        return str(total)
    # special: championship titles -> count 'champion' in column
    if 'champion' in q and 'title' in q:
        cnt = 0
        for c in cols:
            if 'champion' in c.lower() or 'cup' in c.lower() or 'title' in c.lower():
                for i in range(rows):
                    if mask[i] and 'champion' in str(table[c][i]).lower():
                        cnt += 1
        if cnt: return str(cnt)
    total = 0.0
    for i in range(rows):
        if mask[i]:
            v = num(table[target][i])
            if v is not None: total += v
    if total == int(total): return str(int(total))
    return str(total)

def solve(table, question, choices):
    import re
    q = question.lower()
    cols = list(table.keys())
    n = len(next(iter(table.values()))) if table else 0
    rows = [{c: table[c][i] for c in cols} for i in range(n)]

    def find_col(words):
        for c in cols:
            cl = c.lower()
            if any(w in cl for w in words):
                return c
        return None

    def find_row(name):
        name = name.lower()
        for i, r in enumerate(rows):
            for c in cols:
                if r[c].lower() == name:
                    return i
        for i, r in enumerate(rows):
            for c in cols:
                if name in r[c].lower():
                    return i
        raise ValueError("row not found")

    m = re.search(r'(?:after|before|next|previous|following|preceding)\s+(?:the\s+)?(.+?)(?:\?|$)', q)
    if not m:
        raise ValueError("no match")
    target = m.group(1).strip().rstrip('?').strip()
    target = re.sub(r'^(?:a|an|the)\s+', '', target)
    idx = find_row(target)

    direction = 'next'
    if re.search(r'\b(?:before|previous|preceding)\b', q):
        direction = 'prev'

    # determine what to return: the column asked about
    # find column whose header words appear in question
    asked = None
    for c in cols:
        cl = c.lower()
        words = [w for w in re.findall(r'[a-z]+', cl) if len(w) > 2]
        if words and any(w in q for w in words):
            asked = c
            break
    if asked is None:
        # default: the column that contains the target value
        for c in cols:
            if rows[idx][c].lower() == target:
                asked = c
                break
    if asked is None:
        # pick the first column that is not the target column
        for c in cols:
            if rows[idx][c].lower() != target:
                asked = c
                break
    if asked is None:
        raise ValueError("no column")

    # exclude the column that matched the target? Actually we want the answer column
    # If asked column is the same as the column containing the target, pick another
    for c in cols:
        if rows[idx][c].lower() == target:
            if asked == c:
                # find another column
                for c2 in cols:
                    if c2 != c:
                        asked = c2
                        break
                break

    new_idx = idx + 1 if direction == 'next' else idx - 1
    if new_idx < 0 or new_idx >= n:
        raise ValueError("out of range")
    return rows[new_idx][asked]

def solve(table, question, choices):
    import re
    q = question.lower()
    cols = list(table.keys())
    rows = len(table[cols[0]])
    def cell(c, i): return table[c][i]
    def find_col(words):
        for c in cols:
            cl = c.lower()
            if any(w in cl for w in words): return c
        return None
    def find_row(name):
        name = name.lower()
        for i in range(rows):
            for c in cols:
                if name in cell(c, i).lower(): return i
        return None
    # number of divisions for X
    m = re.search(r'number of divisions for (.+)', q)
    if m:
        x = m.group(1).strip().rstrip('?')
        div_col = find_col(['division'])
        season_col = find_col(['season'])
        for i in range(rows):
            if x in cell(season_col, i).lower():
                d = cell(div_col, i)
                m2 = re.search(r'(\d+)', d)
                if m2: return m2.group(1)
        raise Exception('not found')
    # how many silver/bronze/gold medals did X earn
    m = re.search(r'how many (silver|bronze|gold) medals did (.+?) earn', q)
    if m:
        medal = m.group(1)
        who = m.group(2).strip().rstrip('?')
        medal_col = find_col([medal])
        nation_col = find_col(['nation'])
        for i in range(rows):
            if who in cell(nation_col, i).lower():
                return cell(medal_col, i)
        raise Exception('not found')
    # how many people live in X
    m = re.search(r'how many people live in (.+)', q)
    if m:
        place = m.group(1).strip().rstrip('?')
        pop_col = find_col(['population'])
        name_col = find_col(['name'])
        for i in range(rows):
            if place in cell(name_col, i).lower():
                return cell(pop_col, i)
        raise Exception('not found')
    # number of finishers X had
    m = re.search(r'number of finishers (.+?) had', q)
    if m:
        who = m.group(1).strip().rstrip('?')
        country_col = find_col(['country'])
        time_col = find_col(['time'])
        count = 0
        for i in range(rows):
            if who in cell(country_col, i).lower():
                t = cell(time_col, i)
                if t and t != '–' and not t.startswith('DQ'):
                    count += 1
        return str(count)
    # time for the first place medal finisher in the X event
    m = re.search(r'time for the first place medal finisher in the (.+?) event', q)
    if m:
        ev = m.group(1).strip().rstrip('?')
        event_col = find_col(['event'])
        time_col = find_col(['time'])
        for i in range(rows):
            if ev in cell(event_col, i).lower():
                return cell(time_col, i)
        raise Exception('not found')
    raise Exception('unsupported')

def solve(table, question, choices):
    import re
    q = question.lower()
    cols = list(table.keys())
    rows = len(table[cols[0]]) if cols else 0
    def cell(c, i):
        return str(table[c][i]) if c in table and i < len(table[c]) else ""
    # find "other than X" exclusion
    m = re.search(r'other than (.+?)(?:,|\?|$)', q)
    excl = m.group(1).strip() if m else None
    # find numeric condition like "3 bronze medals" or "episode 10"
    num = re.search(r'\b(\d+)\b', q)
    n = int(num.group(1)) if num else None
    # find the column whose cells contain the number/episode
    # strategy: for each column, try to match condition
    best = None
    for c in cols:
        vals = [cell(c, i) for i in range(rows)]
        # numeric column match
        def parse_num(s):
            s = s.replace('–','').replace('-','').replace(',','').strip()
            try: return float(s)
            except: return None
        nums = [parse_num(v) for v in vals]
        if n is not None and any(v == n for v in nums):
            # condition: column equals n
            matches = [i for i in range(rows) if nums[i] == n]
            # exclude excl
            if excl:
                # find which column contains excl value
                excl_rows = set()
                for c2 in cols:
                    for i in range(rows):
                        if excl in cell(c2, i).lower():
                            excl_rows.add(i)
                matches = [i for i in matches if i not in excl_rows]
            # answer column: the column that is not the condition column and not excluded
            # pick the column with most distinct values (the "name" column)
            answer_col = None
            for c3 in cols:
                if c3 == c: continue
                distinct = len(set(cell(c3,i) for i in range(rows)))
                if answer_col is None or distinct > len(set(cell(answer_col,i) for i in range(rows))):
                    answer_col = c3
            if answer_col:
                ans = [cell(answer_col, i) for i in matches]
                ans = [a for a in ans if a]
                if ans:
                    return ', '.join(ans)
        # episode/text match
        if n is not None:
            pat = re.compile(r'episode\s*' + str(n), re.I)
            matches = [i for i in range(rows) if pat.search(vals[i])]
            if matches:
                if excl:
                    excl_rows = set()
                    for c2 in cols:
                        for i in range(rows):
                            if excl in cell(c2, i).lower():
                                excl_rows.add(i)
                    matches = [i for i in matches if i not in excl_rows]
                answer_col = None
                for c3 in cols:
                    if c3 == c: continue
                    distinct = len(set(cell(c3,i) for i in range(rows)))
                    if answer_col is None or distinct > len(set(cell(answer_col,i) for i in range(rows))):
                        answer_col = c3
                if answer_col:
                    ans = [cell(answer_col, i) for i in matches]
                    ans = [a for a in ans if a]
                    if ans:
                        return ', '.join(ans)
    # fallback: find column containing excl value, then find other columns
    if excl:
        excl_rows = set()
        for c2 in cols:
            for i in range(rows):
                if excl in cell(c2, i).lower():
                    excl_rows.add(i)
        # find the column that contains the excl value
        excl_col = None
        for c2 in cols:
            for i in range(rows):
                if excl in cell(c2, i).lower():
                    excl_col = c2
                    break
            if excl_col: break
        # find the other column (the opponent/team)
        other_cols = [c for c in cols if c != excl_col]
        # pick the column with most distinct values
        other_col = max(other_cols, key=lambda c: len(set(cell(c,i) for i in range(rows))))
        ans = set()
        for i in range(rows):
            if i in excl_rows:
                v = cell(other_col, i)
                if v and v.lower() != excl:
                    ans.add(v)
        if ans:
            return ', '.join(sorted(ans))
    raise Exception("unparseable")

def solve(table, question, choices):
    q = question.lower()
    cols = list(table.keys())
    rows = list(zip(*table.values()))
    def col_for(words):
        for c in cols:
            cl = c.lower()
            if any(w in cl for w in words):
                return c
        return None
    def find_rows(name):
        name = name.lower()
        return [r for r in rows if any(str(v).lower() == name or name in str(v).lower() for v in r)]
    if "same surface" in q:
        a, b = q.split(" and ")[0].replace("does the ", "").replace(" tournament", "").strip(), q.split(" and ")[1].replace(" tournament", "").replace(" have the same surface listed?", "").strip()
        ra, rb = find_rows(a), find_rows(b)
        sc = col_for(["surface"])
        if not ra or not rb or not sc: raise ValueError("no")
        return "Yes" if ra[0][cols.index(sc)] == rb[0][cols.index(sc)] else "No"
    if "same quantity" in q:
        parts = q.split(" and ")
        a = parts[0].replace("does the ", "").replace(" have the same quantity as ", "").strip()
        b = parts[1].replace("?", "").strip()
        ra, rb = find_rows(a), find_rows(b)
        qc = col_for(["quantity"])
        if not ra or not rb or not qc: raise ValueError("no")
        return "Yes" if ra[0][cols.index(qc)] == rb[0][cols.index(qc)] else "No"
    if "symbols" in q and "numbers" in q:
        nc = col_for(["name"]) or cols[0]
        vals = [str(r[cols.index(nc)]) for r in rows]
        def is_num(s): return s.isdigit()
        def is_sym(s): return not s.isalnum() and s != ""
        sym_idx = [i for i, s in enumerate(vals) if is_sym(s)]
        num_idx = [i for i, s in enumerate(vals) if is_num(s)]
        if not sym_idx or not num_idx: raise ValueError("no")
        return "Yes" if max(sym_idx) < min(num_idx) else "No"
    raise ValueError("unsupported")

def solve(table, question, choices):
    import re
    from datetime import datetime
    q = question.lower()
    cols = list(table.keys())
    rows = len(next(iter(table.values())))
    # find named items by matching table cells (case-insensitive)
    cells = [c for col in cols for c in table[col] if c]
    names = []
    for cell in cells:
        if cell.lower() in q and cell not in names:
            names.append(cell)
    if len(names) < 2:
        # try splitting on ' or ' / ' and '
        parts = re.split(r"\s+(?:or|and|vs\.?|versus)\s+", question, flags=re.I)
        for p in parts:
            for cell in cells:
                if cell.lower() in p.lower() and cell not in names:
                    names.append(cell)
    if len(names) < 2:
        raise ValueError("need two names")
    names = names[:2]
    # find rows
    def row_for(name):
        for i in range(rows):
            for col in cols:
                if str(table[col][i]).lower() == name.lower():
                    return i
        return None
    rows_idx = [row_for(n) for n in names]
    if any(i is None for i in rows_idx):
        raise ValueError("name not found")
    # detect metric column
    def num(s):
        m = re.search(r"-?\d+(?:\.\d+)?", str(s))
        return float(m.group()) if m else None
    # date column detection
    date_col = None
    for col in cols:
        vals = [str(c) for c in table[col]]
        if any(re.search(r"\d{4}", v) for v in vals):
            date_col = col
            break
    # height column detection
    height_col = None
    for col in cols:
        if "height" in col.lower():
            height_col = col
            break
    # numeric column detection
    def is_numeric_col(col):
        vals = [num(c) for c in table[col]]
        return any(v is not None for v in vals)
    numeric_cols = [c for c in cols if is_numeric_col(c)]
    # question type detection
    if re.search(r"\b(before|after|earlier|later)\b", q):
        if date_col is None:
            raise ValueError("no date col")
        def parse_date(s):
            s = str(s).strip()
            for fmt in ("%d %B %Y", "%B %Y", "%Y", "%d %b %Y", "%b %Y"):
                try:
                    return datetime.strptime(s, fmt)
                except Exception:
                    pass
            m = re.search(r"(\d{4})", s)
            if m:
                return datetime(int(m.group()), 1, 1)
            return None
        d = [parse_date(table[date_col][i]) for i in rows_idx]
        if any(x is None for x in d):
            raise ValueError("bad date")
        if d[0] < d[1]:
            return "before"
        elif d[0] > d[1]:
            return "after"
        return "same"
    if re.search(r"\b(same|equal|identical)\b", q):
        # compare heights or numeric
        if height_col:
            def parse_height(s):
                m = re.search(r"(\d+)'(\d+)\"", str(s))
                if m:
                    return int(m.group(1)) * 12 + int(m.group(2))
                return None
            h = [parse_height(table[height_col][i]) for i in rows_idx]
            if any(x is None for x in h):
                raise ValueError("bad height")
            return "Yes" if h[0] == h[1] else "No"
        # numeric compare
        for col in numeric_cols:
            v = [num(table[col][i]) for i in rows_idx]
            if all(x is not None for x in v):
                return "Yes" if v[0] == v[1] else "No"
        raise ValueError("no compare")
    # numeric comparison
    metric_col = None
    for col in numeric_cols:
        words = set(re.findall(r"[a-z0-9]+", col.lower()))
        qwords = set(re.findall(r"[a-z0-9]+", q))
        if words & qwords:
            metric_col = col
            break
    if metric_col is None:
        # prefer column with 'total' or 'goals' etc.
        for col in numeric_cols:
            if "total" in col.lower():
                metric_col = col
                break
    if metric_col is None:
        metric_col = numeric_cols[0] if numeric_cols else None
    if metric_col is None:
        raise ValueError("no metric")
    vals = [num(table[metric_col][i]) for i in rows_idx]
    if any(v is None for v in vals):
        raise ValueError("bad value")
    if re.search(r"\b(more|higher|greater|larger|taller|heavier|faster|better)\b", q):
        if vals[0] > vals[1]:
            return "Yes" if re.search(r"\b(more|higher|greater|larger|taller|heavier|faster|better)\b", q) else names[0]
        elif vals[0] < vals[1]:
            return "No" if re.search(r"\b(more|higher|greater|larger|taller|heavier|faster|better)\b", q) else names[1]
        return "Yes" if re.search(r"\b(more|higher|greater|larger|taller|heavier|faster|better)\b", q) else names[0]
    # who has more / which is higher
    if re.search(r"\b(who|which|whose|name)\b", q):
        if vals[0] > vals[1]:
            return names[0]
        elif vals[1] > vals[0]:
            return names[1]
        return names[0]
    # default: return which is higher
    if vals[0] > vals[1]:
        return names[0]
    elif vals[1] > vals[0]:
        return names[1]
    return names[0]
